import urllib.request, re, html
def fetch_latest_version():
    url = "https://www.postgresql.org/"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            html_content = response.read().decode('utf-8')
    except Exception as e:
        return f"Error fetching page: {e}"
    # Look for patterns like "PostgreSQL 16.4" or "PostgreSQL 17.0"
    # The homepage often has a line: "PostgreSQL 16.4 Released" or "Latest Release"
    # We'll search for "PostgreSQL " followed by digits and optional dot digits
    match = re.search(r'PostgreSQL\s+(\d+\.\d+)', html_content)
    if match:
        return match.group(1)
    # As fallback, search for "Release" followed by version
    match2 = re.search(r'Release\s+(\d+\.\d+)', html_content)
    if match2:
        return match2.group(1)
    return "Version not found"
latest = fetch_latest_version()
print("Latest version found:", latest)
